const start = 2;
let total = start;
total += 3;
console.log(total);

fn add(left: number, right: number) number {
  return left + right;
}
console.log(add(20, 22));

const parts = ["north", "star"];
const first = parts[0];
const label = { first: first, count: parts.length };
console.log(`${label.first}:${label.count}`);

const parts = ["Deka", "Script"];
let initials = "";
for (const part of parts) {
  initials += part.slice(0, 1);
}
console.log(initials);

const role = "owner";
const label = match (role) {
  "owner" => "Admin",
  "member" => "User",
  _ => "Guest"
};
console.log(label);

struct Point {
  x: number
  y: number
}

const origin = Point { x: 3, y: 4 };
console.log(origin.x + origin.y);

struct Point {
  x: number
  y: number
}

fn (p Point) magnitude() number {
  return Math.sqrt((p.x * p.x) + (p.y * p.y))
}

const p = Point { x: 3, y: 4 };
console.log(p.magnitude());

struct Point {
  x: number
  y: number
}

fn (p mut Point) translate(dx: number, dy: number) void {
  p.x += dx
  p.y += dy
}

let p = Point { x: 1, y: 2 };
p.translate(3, 4);
console.log(p.x + p.y);

struct Person {}

fn (p Person) greet() string {
  return "Hello"
}

struct Employee {
  Person
  name: string
}

fn (e Employee) greet() string {
  return "Hi, " + e.name
}

const e = Employee { name: "DekaScript" };
console.log(e.greet());

struct User {
  name: string
  email: string?
}

const u = User { name: "DekaScript" };

const contact = match (u.email) {
  Some(value) => value,
  None => "no email",
  _ => "unknown"
};

console.log(contact);

enum Status {
  Loading,
  Ready,
  Failed
}

const current = Status.Ready;

const label = match (current) {
  Status.Loading => "Loading...",
  Status.Ready => "Ready",
  Status.Failed => "Failed",
  _ => "Unknown"
};

console.log(label);

const found = Option.Some("DekaScript");

const message = match (found) {
  Some(value) => value,
  None => "nothing",
  _ => "unknown"
};

console.log(message);

async fn fetch_value() Promise<string> {
  return "DekaScript";
}

async fn main() Promise<void> {
  const value = await fetch_value();
  console.log(value);
}

main();

