interface Named {
  name: string
  fn displayName() string
}

struct Person {
  name: string
}

fn (p Person) displayName() string {
  return p.name
}

fn printName(n: Named) {
  console.log(n.displayName())
}

let p = Person { name: "DekaScript" }
printName(p)
